  add('A13','Organization admin','Plan limit reached',admin('Your team has reached its limit','50 enabled employees · hosted Team Free.',`${note('This plan is full. Another employee cannot join yet. No upgrade or charge happens automatically in this preview.','warn')}<div class="grid2">${panel('Current allowance','<h2>50 employees</h2><p>6 months of usage retention.</p>')}${panel('Review the options','<p>Review existing membership or request a different plan. Prices and plan rules still need to be confirmed.</p>'+button('Manage users','A02','primary'))}</div>`,'A12'),{width:1280,height:800,role:'Admin',state:'Capacity limit'});
  add('A14','Organization admin','Overview · narrow screen',`<header class="mobile-head">${logo}<span>Admin</span></header><main class="mobile-page">${badge('Northstar Studio · Admin')}<h1 style="margin-top:22px">Team overview</h1><p class="muted">September 2026 · Sample data</p>${metrics(true)}${panel('Adoption','<div class="mini-stat"><span>Active users</span><b>38</b></div><div class="mini-stat"><span>Installations</span><b>67</b></div>')}${note('87% resource-estimate coverage. Hidden processing is not included.')}${button('Manage users','A02','primary')}</main>`,{width:390,height:900,role:'Admin',state:'Narrow screen'});
